/**
 * NODE 2 - Dynamic Actions List Options
 *
 * Builds `actions_array` for the type the agent picked on node 1, and records the VI
 * COMBINED PNR (built by node 83) as the single customer-action row the table on
 * nodes 12/25 renders.
 *
 * Inputs:
 *   type                        node 1's select - holds the Edvin type ID
 *   transforms.actions_by_type  { "<typeId>": [action] }, built by node 81 (Format Types)
 *   transforms.channel          Edvin channel object (node 81)
 *   transforms.category         Edvin category object (node 81)
 *   transforms.current_pnr      the combined PNR record (node 83)
 *   notes                       agent free-text notes from node 1
 *   partner / disruption_type / delay_reason / flight_affected / stg_*  the VI screens
 *
 * Outputs:
 *   transforms.actions_array         normalized actions for the selected type
 *   transforms.customer_action_pnrs  [combined record] - upserted by PNR
 *   transforms.vi_details            the VI/STG answers as an object
 *   transforms.vi_details_text       the same answers as printable text
 *
 * ONE PRODUCER OF BUCKET KEYS. Node 81 already normalizes every action in the category
 * (bucket -> routing key, bucketId, actionId) and groups them by type id, so this node
 * READS that grouping instead of re-mapping the raw API objects. The old copy of the
 * mapping here used the bucket LABEL only, which is why every bucket except "Proceed"
 * reached node 27 unusable. Two copies of that logic is how the bug came back; there is
 * now exactly one.
 */

let type_id = ZT.getVariableValue("type", "");
let category = transforms.category;
let channel = transforms.channel;

if (!category || !channel) {
  ZT.log("node 2 | transforms.category/channel missing - node 81 (Format Types) must run " +
         "before this node. No actions can be resolved.");
}

const actions_by_type = transforms.actions_by_type || {};
const types = (category && category.types) || [];
const selected_type = types.find(x => String(x.id) === String(type_id)) || { name: "", actions: [] };

// Node 81's normalized list for this type. Fallback covers a session where node 81 has not
// run (or a type Edvin returned with no actions) - it uses the SAME id-first bucket rules,
// kept identical to node 81 on purpose.
const BUCKET_BY_ID = { 3: "no_action", 4: "proceed", 5: "different_request" };

const BUCKET_BY_NAME = {
  "no action": "no_action",
  "no_action": "no_action",
  "do not proceed": "no_action",
  "proceed": "proceed",
  "different request": "different_request",
  "different_request": "different_request"
};

const BUCKET_NAME_KEYS = ["name", "value", "key", "label", "code", "slug", "type", "bucketKey"];

function rawBucketName(b) {
  if (typeof b === "string") return b;
  for (let i = 0; i < BUCKET_NAME_KEYS.length; i++) {
    const v = b[BUCKET_NAME_KEYS[i]];
    if (typeof v === "string" && v.trim() !== "") return v;
  }
  return "";
}

// An unmapped bucket is returned UNCHANGED, never guessed - node 27 flags it rather than
// risk routing an unknown bucket as the wrong one.
function bucketKey(b) {
  if (!b) return "";
  if (b.id != null && BUCKET_BY_ID[b.id]) return BUCKET_BY_ID[b.id];
  const raw = rawBucketName(b);
  if (!raw) return "";
  return BUCKET_BY_NAME[raw.trim().toLowerCase()] || raw;
}

let actions_array = actions_by_type[String(type_id)];
if (!Array.isArray(actions_array) || !actions_array.length) {
  actions_array = (selected_type.actions || []).map(action => ({
    ...action,
    bucket: bucketKey(action.bucket),
    bucketId: action.bucket && action.bucket.id,
    actionId: action.id
  }));
  ZT.log("node 2 | actions_by_type had no entry for type " + JSON.stringify(String(type_id)) +
         " - fell back to mapping category.types locally");
}

ZT.log("node 2 | type=" + JSON.stringify(selected_type.name) +
       " | actions=" + actions_array.length +
       " | buckets=" + JSON.stringify(actions_array.map(a => a.bucket)));

ZT.setTransformData("actions_array", actions_array);

// The VI / STG answers collected on nodes 48-76. Captured here because node 1 is the first
// node reached after every VI screen, so whatever the agent picked is final by now.
const VI_FIELDS = [
  ["Partner", "partner"],
  ["Order created", "orderCreated"],
  ["Disruption type", "disruption_type"],
  ["Delay reason", "delay_reason"],
  ["Flight affected", "flight_affected"],
  ["Same day alternative (schedule change)", "stg_alternatives_sameday_sc"],
  ["Next day alternative (schedule change)", "stg_alternatives_overnight_sc"],
  ["Same day alternative (trip delay)", "stg_alternatives_sameday_td"],
  ["Next day alternative (trip delay)", "stg_alternatives_overnight_td"],
  ["Refund offer", "stg_refund"]
];

let vi_details = {};
let vi_lines = [];
VI_FIELDS.forEach(([label, name]) => {
  const value = ZT.getVariableValue(name, "");
  if (!value) return;
  vi_details[name] = value;
  vi_lines.push(label + ": " + value);
});
const vi_details_text = vi_lines.join("\n");

ZT.setTransformData("vi_details", vi_details);
ZT.setTransformData("vi_details_text", vi_details_text);
ZT.setFormData("vi_details_text", vi_details_text);

// The VI answers ride along on `notes`, which is the field the parent tree already prints
// in the Zendesk internal note (its node 21) and in the Edvin errand free text (its node
// 44, "Agent Notes"). No parent-side change is needed for them to show up in both.
const agent_notes = ZT.getVariableValue("notes", "");
const notes = [agent_notes, vi_details_text ? "VI / STG details\n" + vi_details_text : ""]
  .filter(Boolean)
  .join("\n\n");

// Record this errand on the running list of customer-action PNRs. On the VI path this is
// the ONE combined PNR record, so the list holds exactly one row.
let current_pnr = {
  ...transforms.current_pnr,
  channel: channel && channel.name,
  channelId: channel && channel.id,
  category: category && category.name,
  categoryId: category && category.id,
  type: selected_type.name,
  typeId: type_id,
  notes,
  vi_details,
  vi_details_text,
  actions_array
  // actionId / customer_action / bucket added downstream by node 27
};

// Upsert by PNR so re-running this node for the same combined PNR (Back navigation, or a
// ?session_id= deep-resume that re-enters past node 83) overwrites that row instead of
// adding a duplicate action card.
let customer_action_pnrs = transforms.customer_action_pnrs || [];
let existingIndex = customer_action_pnrs.findIndex(p => p.pnr === current_pnr.pnr);
if (existingIndex >= 0) {
  customer_action_pnrs[existingIndex] = current_pnr;
} else {
  customer_action_pnrs.push(current_pnr);
}
ZT.setTransformData("customer_action_pnrs", customer_action_pnrs);

