// Resolves the Edvin channel + category for this contact, and builds the
// type -> actions groupings the downstream action selects read from.
//
// Grouped three ways because a Zingtree dynamic list source addresses a transform
// by path, and which key that path can carry depends on whether the selected
// `type` field holds an id or a name:
//   transforms.types_list           [{id, name}]               - the TYPE select
//   transforms.actions_by_type      { "<typeId>":   [action] } - path keyed by id
//   transforms.actions_by_type_name { "<typeName>": [action] } - path keyed by name
//   transforms.actions_flat         [action + type_id/type_name] - one list, all types
//
// Every action carries the same shape node 2 produces - drop-in compatible with
// transforms.actions_array: { id, name, bucket (STRING), bucketId, actionId,
// edvin_actions, type_id, type_name }

let errand_configuration = actions.edvin__errand_configuration;
let edvin_prop_long_val = actions.get_edvin_prop_long_value;

// Maps the Zendesk contact-reason field to the Edvin category name, until Edvin
// returns a value that matches the Zendesk field directly.
const CONTACT_REASON_BY_ZENDESK = {
  "contact_reason__rebooking": "Rebooking",
  "contact_reason__cancellation": "Cancellation",
  "contact_reason__refund": "Refund",
  "contact_reason__name_correction_change": "Name Correction/Change",
  "contact_reason__add_passenger": "Add Passenger/New ticket sell",
  "contact_reason__change_customers_personal_information": "Change customer's personal information",
  "contact_reason__document_travel_info": "Document & Travel Info",
  "contact_reason__payment_question": "Payment Question",
  "contact_reason__ancillaries_products": "Ancillaries/Services & Products",
  "contact_reason__unconfirmed_booking": "Unconfirmed booking",
  "contact_reason__site_support": "Site support",
  "contact_reason__ongoing_issues": "Ongoing issues",
  "contact_reason__other": "Other",
  // SCHEDULE CHANGE //
  "contact_reason__schedule_change": "Rebooking",
  "contact_reason__cancellation_sc": "Cancellation",
  "contact_reason__self_transfer_guarantee_vi_sc": "Self Transfer Guarantee (VI) - SC",
  "contact_reason__self_transfer_guarantee_vi_passengers_at_the_airport": "Self Transfer Guarantee (VI) - Passengers at the airport",
  "contact_reason__refund_sc": "Refund",
  "contact_reason__ancillaries_products_sc": "Ancillaries/Services & Products",
  "contact_reason__document_travel_info_sc": "Document & Travel Info",
  "contact_reason__other_sc": "Other"
};
const ZENDESK_VALUE = ZT.getVariableValue("custom_field_29658558478738", "");
const CONTACT_REASON = CONTACT_REASON_BY_ZENDESK[ZENDESK_VALUE] || "";

function findCancellation() {
  const channel = errand_configuration.channels.find(c => c.id === edvin_prop_long_val.value);
  if (!channel) {
    throw new Error(`No Edvin channel found for id ${edvin_prop_long_val.value}`);
  }
  const category = channel.categories.find(c => c.name === CONTACT_REASON);
  if (!category) {
    // Log the options BEFORE throwing - the thrown message alone does not tell you whether
    // the Zendesk value is unmapped above or the Edvin category was renamed.
    // KNOWN GAP: the parent tree's node 75 also routes the bare
    // contact_reason_sc__self_transfer_guarantee_vi into this subtree, and that value has
    // no entry in CONTACT_REASON_BY_ZENDESK, so it lands here. Decide with ETG which leaf
    // category it means before this reaches more agents.
    ZT.log("node 81 | no category match | zendesk=" + JSON.stringify(ZENDESK_VALUE) +
           " | resolved=" + JSON.stringify(CONTACT_REASON) +
           " | channel=" + JSON.stringify(channel.name) +
           " | categories offered=" + JSON.stringify(channel.categories.map(c => c.name)));
    throw new Error(`No Edvin category match for Zendesk value "${ZENDESK_VALUE}" (resolved name: "${CONTACT_REASON}") in channel "${channel.name}"`);
  }
  return { channel, category };
}

let result = findCancellation();
ZT.setTransformData("category", result.category);
ZT.setTransformData("channel", result.channel);

// Edvin returns bucket as { id, name }. Match on id first - it's the stable
// contract, while the label is display text ETG can reword any time. The name
// map is the fallback for a bucket that arrives as a bare string.
// This node is the ONLY producer of bucket routing keys in this tree - node 2 reads
// transforms.actions_by_type instead of re-mapping. Keep it that way.
const BUCKET_BY_ID = { 3: "no_action", 4: "proceed", 5: "different_request" };

const BUCKET_BY_NAME = {
  "no action": "no_action",
  "no_action": "no_action",
  "do not proceed": "no_action",
  "proceed": "proceed",
  "different request": "different_request",
  "different_request": "different_request"
};

const BUCKET_NAME_KEYS = ["name", "value", "key", "label", "code", "slug", "type", "bucketKey"];

function rawBucketName(b) {
  if (typeof b === "string") return b;
  for (let i = 0; i < BUCKET_NAME_KEYS.length; i++) {
    const v = b[BUCKET_NAME_KEYS[i]];
    if (typeof v === "string" && v.trim() !== "") return v;
  }
  return "";
}

// An unmapped bucket is returned UNCHANGED, never guessed - node 27 flags it and
// stops the run rather than risk routing an unknown bucket as the wrong one.
function bucketKey(b) {
  if (!b) return "";
  if (b.id != null && BUCKET_BY_ID[b.id]) return BUCKET_BY_ID[b.id];
  const raw = rawBucketName(b);
  if (!raw) return "";
  return BUCKET_BY_NAME[raw.trim().toLowerCase()] || raw;
}

const types = result.category.types || [];

const types_list = [];
const types_by_id = {};
const actions_by_type = {};
const actions_by_type_name = {};
const actions_flat = [];

types.forEach(type => {
  const typeId = String(type.id);
  const typeName = type.name || "";

  types_list.push({ id: type.id, name: typeName });
  types_by_id[typeId] = type;

  const mapped = type.actions.map(action => ({
    ...action,
    bucket: bucketKey(action.bucket),
    bucketId: action.bucket && action.bucket.id,
    actionId: action.id,
    type_id: type.id,
    type_name: typeName
  }));

  actions_by_type[typeId] = mapped;
  actions_by_type_name[typeName] = mapped;
  mapped.forEach(a => actions_flat.push(a));
});

ZT.setTransformData("types_list", types_list);
ZT.setTransformData("types_by_id", types_by_id);
ZT.setTransformData("actions_by_type", actions_by_type);
ZT.setTransformData("actions_by_type_name", actions_by_type_name);
ZT.setTransformData("actions_flat", actions_flat);

