// NODE 82 - Partner / order-age route
//
// Picks which STG rule set the contact follows and hands node 49 a single scalar:
//   route = "50"  Booking, OR an ETG order created before the 21 May 2026 cutoff
//   route = "66"  everything else (ETG, on or after the cutoff)
//
// Two things this guards that the first version did not:
//
// 1. DATE-ONLY, TIMEZONE-FREE COMPARISON. `new Date('2026-05-21T00:00:00')` is parsed as
//    LOCAL midnight, while Edvin's orderCreated is an ISO timestamp (usually UTC). An
//    order created late on 20 May UTC could land either side of a local-midnight cutoff
//    depending on where the engine runs. Comparing the YYYY-MM-DD prefixes as strings is
//    exact and has no timezone in it at all.
//    BOUNDARY: an order created ON 2026-05-21 routes to node 66, unchanged from the
//    original `< 2026-05-21T00:00:00`. Node 50 is titled "prior 21May26" and node 66
//    "post 22may2026", so the 21st itself is not described by either title - confirm with
//    ETG which side owns it before this goes to more agents.
//
// 2. THE ORDER DATE HAS TWO SOURCES. Node 48 carries an `orderCreated` date field (the
//    manual/testing entry) and the Edvin order lookup carries the real value. The agent's
//    entry wins when present, then the API, and if neither is readable the route falls
//    back to "66" (the current rules) and says so in the log - instead of `new Date(undefined)`
//    silently comparing false.

function datePart(value) {
  if (!value) return "";
  const s = String(value).trim();
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + "-" + m[2] + "-" + m[3];
  // Fall back to a real parse for formats like "05/21/2026" that the agent field may post.
  const d = new Date(s);
  if (isNaN(d.getTime())) return "";
  const pad = n => (n < 10 ? "0" + n : String(n));
  return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
}

const CUTOFF = "2026-05-21";

const partner = ZT.getVariableValue("zd_brand_name", "");
const agentEnteredDate = ZT.getVariableValue("orderCreated", "");
const apiDate = (actions.findorder && actions.findorder.orderCreated) || "";
const order_created = datePart(agentEnteredDate) || datePart(apiDate);

let route = "66";
if (partner == "Booking" || (order_created && order_created < CUTOFF)) {
  route = "50";
}

ZT.setFormData("route", route);
ZT.setFormData("order_created_date", order_created);

ZT.log("node 82 | partner=" + JSON.stringify(partner) +
       " | orderCreated(agent)=" + JSON.stringify(agentEnteredDate) +
       " | orderCreated(api)=" + JSON.stringify(apiDate) +
       " | resolved=" + JSON.stringify(order_created) +
       " | cutoff=" + CUTOFF +
       " | route=" + route +
       (order_created ? "" : " | WARNING no readable order date - routed by partner only"));

